package edalign

import (
	"github.com/stretchr/testify/assert"
	"testing"
)

func TestAlignExact(t *testing.T) {
	var (
		seq1 = IUPAC.Transform("ATCG")
		seq2 = IUPAC.Transform("ATCG")
	)

	cfg := DefaultConfig()
	cfg.Task = TaskLocation

	result, err := Align(seq1, seq2, cfg)
	assert.NoError(t, err)

	t.Logf("distance: %d/%d %.2f%%", result.EditDistance, len(seq2), result.PercentIdentity)
	t.Logf("locations: %v %v", result.StartLocations, result.EndLocations)

	assert.Equal(t, 0, result.EditDistance)
}

func TestAlignGap(t *testing.T) {
	var (
		seq1 = IUPAC.Transform("ACT")
		seq2 = IUPAC.Transform("CGACTGAC")
	)

	result, err := Align(seq1, seq2, DefaultConfig())
	assert.NoError(t, err)

	t.Logf("distance: %d/%d %.2f%%", result.EditDistance, len(seq2), result.PercentIdentity)

	assert.Equal(t, 0, result.EditDistance)
}

func TestAlignAmbiguous(t *testing.T) {
	t.Run("N match", func(t *testing.T) {
		var (
			seq1 = IUPAC.Transform("NNN")
			seq2 = IUPAC.Transform("ATCG")
		)

		result, err := Align(seq1, seq2, DefaultConfig())
		assert.NoError(t, err)

		t.Logf("distance: %d/%d %.2f%%", result.EditDistance, len(seq2), result.PercentIdentity)

		assert.Equal(t, 0, result.EditDistance)
	})

	t.Run("R match", func(t *testing.T) {
		var (
			seq1 = IUPAC.Transform("RRR")
			seq2 = IUPAC.Transform("AGAA")
		)

		result, err := Align(seq1, seq2, DefaultConfig())
		assert.NoError(t, err)

		t.Logf("distance: %d/%d %.2f%%", result.EditDistance, len(seq2), result.PercentIdentity)

		assert.Equal(t, 0, result.EditDistance)
	})
	t.Run("R no match", func(t *testing.T) {
		var (
			seq1 = IUPAC.Transform("RRR")
			seq2 = IUPAC.Transform("CTCC")
		)

		result, err := Align(seq1, seq2, DefaultConfig())
		assert.NoError(t, err)

		t.Logf("distance: %d/%d %.2f%%", result.EditDistance, len(seq2), result.PercentIdentity)

		assert.Equal(t, 3, result.EditDistance)
	})
}

func TestAlign16sUnambiguous(t *testing.T) {
	var (
		seq1 = IUPAC.Transform(``)
		seq2 = IUPAC.Transform(``)
	)

	cfg := DefaultConfig()
	cfg.Task = TaskDistance | TaskPath | TaskLocation

	result, err := Align(seq1, seq2, cfg)
	assert.NoError(t, err)

	t.Run("EditDistance", func(t *testing.T) {
		assert.Equal(t, 8, result.EditDistance)
	})

	t.Run("PercentIdentity", func(t *testing.T) {
		assert.Equal(t, float64(1530-8)/1530*100, result.PercentIdentity)
	})
	t.Run("EndLocations", func(t *testing.T) {
		assert.Equal(t, 1, len(result.EndLocations))
		assert.Equal(t, 1538, result.EndLocations[0])
	})
	t.Run("StartLocations", func(t *testing.T) {
		assert.Equal(t, 1, len(result.StartLocations))
		assert.Equal(t, 9, result.StartLocations[0])
	})
	t.Run("AlignmentLength", func(t *testing.T) {
		assert.Equal(t, 1530, len(result.Alignment))
	})
	t.Run("AlignmentCigar", func(t *testing.T) {
		assert.Equal(t, "85=X912=3X14=X112=2X318=X81=", result.Alignment.String())
	})
}

func BenchmarkAlign(b *testing.B) {
	cfg := DefaultConfig()

	var (
		seq1 = IUPAC.Transform(``)
		seq2 = IUPAC.Transform(``)
	)

	for i := 0; i < b.N; i++ {
		_, _ = Align(seq1, seq2, cfg)
	}
}
